import sys; sys.path.insert(0,'/home/claude/ac-mdcu/parts')
from l23_common import mk, save
Q={}

mk(Q, 111, [68, 's22', 's23'],
 stem='A 42-year-old man with 50% TBSA burns is intubated and has a central venous catheter and a urinary catheter. On day 10 he develops a temperature of 39.5 °C with new tachycardia. Which group lists the principal sites to evaluate for infection?',
 opts=['Paranasal sinuses, middle ear and oropharynx','Skin graft donor sites and dressing surfaces','Blood, burn wound, lungs and urinary tract','Liver, spleen, pancreas, gallbladder and appendix','Central nervous system, eyes, joints and long bones'],
 interp='ไหม้ 50% ใส่ท่อช่วยหายใจ สายสวนหลอดเลือดดำส่วนกลาง และสายสวนปัสสาวะ วันที่ 10 ไข้สูงขึ้นชัดร่วมกับหัวใจเต้นเร็วขึ้นใหม่ → สงสัย sepsis → ถามว่าต้องไล่หาแหล่งติดเชื้อที่ไหนก่อน ต้องใช้หลักว่าแหล่งหลักมาจากแผลไหม้และอุปกรณ์ที่สอดใส่ร่างกาย',
 why='ผู้ป่วยไหม้กว้างติดเชื้อง่ายเพราะ<b>แผลเปรียบเหมือนจานเพาะเชื้อขนาดใหญ่</b> ภูมิคุ้มกันถูกกด และมี<b>อุปกรณ์สอดใส่</b>ที่ข้ามกลไกป้องกันของร่างกาย — แหล่งติดเชื้อหลักจึงมี 4 แห่ง: <b>กระแสเลือด</b> (central line-associated bloodstream infection, suppurative thrombophlebitis) · <b>แผลไหม้</b> (ตั้งแต่ colonization จนถึง invasive infection) · <b>ทางเดินหายใจส่วนล่าง</b> (ventilator-associated pneumonia โดยเฉพาะเมื่อมี inhalation injury) · <b>ทางเดินปัสสาวะ</b> (catheter-associated UTI) · การประเมินคือตรวจแผลทุกจุด เพาะเชื้อเลือดทั้งจากสายและจากเส้นใหม่ เก็บเสมหะจากท่อ และส่งปัสสาวะ · ไข้อย่างเดียวแปลยากเพราะ burn มี<b>อุณหภูมิพื้นฐานสูงจาก hypermetabolism</b> แม้ไม่ติดเชื้อ ABA 2007 จึงใช้ไข้ &gt; 39 °C หรือ &lt; 36.5 °C ร่วมกับเกณฑ์อื่น เช่น หัวใจเต้นเร็วขึ้นต่อเนื่อง หายใจเร็ว เกล็ดเลือดลด น้ำตาลสูง และรับอาหารทางสายไม่ได้ · แหล่งรองอย่าง sinusitis, acalculous cholecystitis และ osteomyelitis ค่อยไล่หาเมื่อ 4 แหล่งหลักไม่พบ · สไลด์หน้า 68 <b>"Sites: Blood stream · Burn wound · Lower respiratory tract · Urinary tract"</b>',
 wrong={
 'A':'ไซนัสอักเสบและหูชั้นกลางอักเสบเกิดได้จริงในผู้ป่วยที่ใส่ท่อทางจมูกหรือสายให้อาหารนาน แต่เป็น<b>แหล่งรอง</b>ที่ไล่หาเมื่อเพาะเชื้อจากแหล่งหลักไม่พบ ไม่ใช่กลุ่มแรกที่ต้องตรวจ · ไม่มีสถานการณ์ใดที่กลุ่มนี้เป็นชุดแหล่งหลักของ burn sepsis เพราะขาดแผลไหม้ กระแสเลือด ปอด และปัสสาวะ ซึ่งเป็นที่มาของการติดเชื้อส่วนใหญ่',
 'B':'Donor site เป็นแผลตื้นที่ติดเชื้อได้และต้องตรวจร่วมกับแผลไหม้เสมอ แต่เป็นเพียงส่วนเล็กของผิวที่บาดเจ็บ และกลุ่มนี้ขาดกระแสเลือด ปอด และปัสสาวะที่มีอุปกรณ์สอดใส่อยู่ · จะถูกถ้าหญิงไหม้ 6% ที่แขนได้ skin graft จนแผลไหม้และกราฟต์ติดดีแล้ว ไม่มีสายสวนใดเหลืออยู่ มาด้วยไข้ต่ำและเจ็บที่ donor site ต้นขาซึ่งยังปิด dressing อยู่',
 'D':'ถุงน้ำดีอักเสบแบบไม่มีนิ่ว (acalculous cholecystitis) และตับอ่อนอักเสบเกิดได้ในผู้ป่วยวิกฤตที่ไหม้กว้าง แต่พบน้อยและนึกถึงเมื่อมีอาการทางช่องท้องหรือหาแหล่งหลักไม่พบ ส่วนม้ามและไส้ติ่งแทบไม่เป็นแหล่ง · ไม่มีสถานการณ์ใดที่อวัยวะในช่องท้องชุดนี้เป็นแหล่งหลักที่ต้องไล่ก่อนใน burn sepsis เพราะความเสี่ยงหลักมาจากแผลและอุปกรณ์สอดใส่',
 'E':'Osteomyelitis พบได้เมื่อแผลลึกถึงกระดูก ส่วนเยื่อหุ้มสมองอักเสบ ตาอักเสบ และข้ออักเสบมักเป็นผลตามหลัง bacteremia หรือ candidemia จึงเป็นปลายทางของเชื้อจากแหล่งหลักมากกว่าจุดเริ่มต้น · ไม่มีสถานการณ์ใดที่กลุ่มนี้เป็นชุดแหล่งหลักใน burn sepsis เพราะไม่มีแผลและอุปกรณ์ที่เป็นทางเข้าของเชื้อ'},
 trap='ไข้วันที่ 10 ชวนให้โทษแผลไหม้อย่างเดียว หรือเลือกกลุ่มอวัยวะไกลที่ฟังดูครบถ้วน · วิธีแยก: นับแผลและอุปกรณ์ที่ผู้ป่วยมีอยู่ แต่ละอย่างคือทางเข้าของเชื้อ — ท่อช่วยหายใจ = ปอด · central line = กระแสเลือด · Foley = ปัสสาวะ · บวกแผลไหม้ = 4 แหล่งหลัก',
 summary=['แหล่งติดเชื้อหลักใน burn = Blood stream · Burn wound · Lower respiratory tract · Urinary tract (สไลด์หน้า 68)',
  'ชีทหน้า 22: ถ้าไม่มี inhalation injury สาเหตุการตายสำคัญที่สุดของ burn รุนแรงคือ systemic sepsis',
  'อุปกรณ์สอดใส่ (ท่อช่วยหายใจ สายสวนปัสสาวะ สายหลอดเลือด) ทำลายกลไกป้องกัน → suppurative thrombophlebitis พบบ่อย',
  'ไข้อย่างเดียวไม่พอ: ABA 2007 ใช้ไข้ &gt; 39 หรือ &lt; 36.5 °C · หัวใจเต้น &gt; 110 · หายใจ &gt; 25 · เกล็ดเลือด &lt; 100,000 · น้ำตาลสูง · รับอาหารทางสายไม่ได้ — ต้อง ≥ 3 ข้อร่วมกับหลักฐานติดเชื้อ',
  'ชีทหน้า 23: เชื้อประจำหน่วยที่พบบ่อย Pseudomonas aeruginosa และ S. aureus · Candida เป็นเชื้อราที่พบบ่อยที่สุด',
  'แหล่งรองเมื่อแหล่งหลักไม่พบ: sinusitis จากท่อทางจมูก · acalculous cholecystitis · osteomyelitis (ชีทหน้า 22) · endocarditis'],
 opinion='เห็นด้วยกับคำตอบ C ความมั่นใจสูง — ตรงกับสไลด์หน้า 68 และชีทหน้า 22 ที่ระบุทางเดินหายใจ ทางเดินปัสสาวะ และสายที่สอดใส่เส้นเลือดเป็นแหล่งติดเชื้อสำคัญ และสอดคล้องกับ ABA consensus 2007 · จุดที่ชีทหน้า 22 ต่างจากปัจจุบัน: เขียนให้เปลี่ยนสายที่สอดใส่เส้นเลือดทุก 72 ชั่วโมง ซึ่งใช้ได้กับ peripheral line แต่ CDC 2011 ไม่แนะนำเปลี่ยน central line ตามรอบเวลา ให้ถอดเมื่อหมดความจำเป็นหรือสงสัยว่าติดเชื้อ',
 mnemonic='<b>“แผล–เลือด–ปอด–ฉี่: ทุกท่อคือประตูเชื้อ”</b>',
 guide="ABA Consensus Conference to Define Sepsis and Infection in Burns (J Burn Care Res 2007;28:776–790); CDC Guidelines for the Prevention of Intravascular Catheter-Related Infections (2011); Sabiston Textbook of Surgery 21st ed. (2022) — Burns",
 variants=['ชายไหม้ 40% ใส่สายให้อาหารทางจมูกมา 2 สัปดาห์ เพาะเชื้อเลือด เสมหะ ปัสสาวะ และชิ้นเนื้อแผลไม่พบเชื้อ แต่ยังไข้และมีน้ำมูกข้นข้างเดียว → CT ไซนัสหา nosocomial sinusitis แล้วย้ายสายไปทางปาก',
  'หญิงไหม้ 55% ใช้ vasopressor ไข้ไม่ลง กดเจ็บใต้ชายโครงขวา อัลตราซาวนด์เห็นถุงน้ำดีผนังหนาไม่มีนิ่ว → acalculous cholecystitis ทำ percutaneous cholecystostomy',
  'ชายไหม้ 30% ไข้หนาวสั่น เส้นเลือดดำที่แขนซึ่งเคยให้น้ำเกลือแข็งเป็นลำ กดแล้วมีหนองออกที่รอยเข็ม → suppurative thrombophlebitis ถอดสาย ผ่าตัดเลาะเส้นเลือดที่ติดเชื้อออก และให้ยาฆ่าเชื้อ'])

mk(Q, 112, [70, 's24'],
 stem='A 36-year-old woman on day 9 after a 45% TBSA burn becomes hypotensive and confused. Part of her thigh wound has turned black, smells foul and is separating early. Which plan is most appropriate?',
 opts=['Organ support, eschar excision and systemic antibiotics','Defer debridement until fever and shock have resolved','Switch the topical agent and continue daily dressings','Start broad-spectrum antibiotics and await culture results','Withhold enteral feeding and begin complete bowel rest'],
 interp='ไหม้ 45% วันที่ 9 ความดันต่ำ สับสน แผลที่ต้นขาดำ เหม็น และ eschar หลุดเร็ว → invasive burn wound infection ที่ทำให้เกิด septic shock → ถามแผนรักษาที่ครบ ต้องใช้หลักพยุงอวัยวะ + กำจัดแหล่งเชื้อ + ให้ยาเข้าระบบไปพร้อมกัน',
 why='ผู้ป่วย burn ที่ <b>clinically septic</b> ต้องทำ 4 อย่างพร้อมกัน: (1) <b>cardiopulmonary support</b> — สารน้ำ vasopressor (norepinephrine เป้า MAP ≥ 65 mmHg) และช่วยหายใจ · (2) <b>GI support</b> — ให้อาหารทางลำไส้ต่อเท่าที่ทนได้และป้องกัน stress ulcer (Curling ulcer) · (3) <b>source control</b> — ตัด eschar ที่ติดเชื้อออกให้ถึงเนื้อดี และถอดสายสวนที่อาจเป็นต้นเหตุ เพราะยาเข้าไม่ถึงเนื้อตายที่ไม่มีเลือดเลี้ยง · (4) <b>systemic antibiotics</b> — เก็บเพาะเชื้อแล้วให้ <b>empirical</b> ตามเชื้อประจำหน่วย (มักต้องคลุม Pseudomonas และ S. aureus รวม MRSA) ภายใน 1 ชั่วโมงเมื่อมี shock แล้วปรับตามผล · ถ้ายังคุมไม่ได้ให้เปลี่ยนยาทาแผลร่วมด้วย · แผลดำ เหม็น eschar หลุดเร็ว คือสัญญาณ invasive infection ที่รอไม่ได้ ผ่าตัดทันทีที่ resuscitate จนพอดมยาได้ · สไลด์หน้า 70 <b>"Cardiopulmonary support · GI system support · Eschar debridement · Systemic antibiotics"</b>',
 wrong={
 'B':'การเลื่อนผ่าตัดจนไข้และ shock หายฟังดูปลอดภัย แต่ใน burn wound sepsis เนื้อตายที่ติดเชื้อคือต้นเหตุ ไข้และ shock จะไม่หายจนกว่าจะเอาออก ทำได้ทันทีหลัง resuscitate ให้พอผ่าตัดได้ · จะถูกถ้าชายไหม้ 30% ที่ septic shock จาก central line โดยแผลสะอาด กราฟต์ติดดี และมีนัดตัดแผลส่วนที่เหลือแบบ elective ซึ่งควรเลื่อนการผ่าตัดที่ไม่เร่งด่วนและถอดสายแทน',
 'C':'การเปลี่ยนยาทาแผล เช่นจาก silver sulfadiazine เป็น mafenide ที่ซึมผ่าน eschar ได้ดีกว่า ชีทหน้า 24 ใช้เมื่อคุมการติดเชื้อไม่ได้ เป็นส่วนเสริม ไม่ใช่การรักษาหลักใน septic shock · จะถูกถ้าหญิงไหม้ 25% สัญญาณชีพปกติ แผลยังดูดี แต่ quantitative culture สัปดาห์นี้เพิ่มขึ้นใกล้ 10⁵ ต่อกรัม และ histology ไม่พบเชื้อบุกเนื้อดี',
 'D':'ยาฆ่าเชื้อกว้างและการเพาะเชื้อเป็นส่วนที่จำเป็น แต่ยาเข้าไม่ถึง eschar ที่ไม่มีเลือดเลี้ยง ถ้าไม่ตัดแหล่งเชื้อและไม่พยุงหัวใจปอด sepsis จะไม่หาย · จะถูกถ้าชายไหม้ 35% ที่แผลสะอาดกำลังหาย ความดันปกติ มีไข้ เสมหะเป็นหนอง และภาพรังสีปอดมีฝ้าใหม่ ซึ่งเป็น ventilator-associated pneumonia ที่ไม่มีเนื้อตายให้ตัด',
 'E':'Bowel rest ขัดกับ GI system support เพราะลำไส้ที่ไม่ได้ใช้ทำให้เยื่อบุฝ่อ เชื้อผ่านเข้ากระแสเลือดง่าย และผู้ป่วย sepsis ต้องการพลังงานสูงขึ้นอีก · จะถูกถ้าหญิงไหม้ 60% ที่ใช้ vasopressor ขนาดสูง ท้องอืดตึง lactate ขึ้นต่อเนื่อง และสงสัย nonocclusive mesenteric ischemia ซึ่งต้องหยุดอาหารทางลำไส้และประเมินผ่าตัด'},
 trap='ช้อย B ฟังรอบคอบและช้อย D ฟังทันสมัย — แต่ทั้งคู่ขาด source control · วิธีแยก: ถามว่าแหล่งเชื้ออยู่ที่ไหนและตัดออกได้หรือไม่ ถ้าเป็น eschar ที่ติดเชื้อ แผนที่ถูกต้องต้องมีการตัดเนื้อตายเสมอ ร่วมกับพยุงอวัยวะและยาเข้าระบบ',
 summary=['Clinically septic burn = Cardiopulmonary support + GI system support + Eschar debridement + Systemic antibiotics (สไลด์หน้า 70)',
  'ชีทหน้า 24: สิ่งแรกคือกำจัดสาเหตุ — ตัด eschar ที่ติดเชื้อ และถอดสายสวนที่อาจเป็นต้นเหตุ',
  'ยา: รู้เชื้อ → ให้ตามผลเพาะเชื้อ · ไม่รู้ → empirical ตามเชื้อประจำหน่วยแล้วรีบเพาะเชื้อ',
  'Septic shock: ยาฆ่าเชื้อภายใน 1 ชั่วโมง · norepinephrine เป้า MAP ≥ 65 mmHg (SSC 2021)',
  'GI support: ให้อาหารทางลำไส้ต่อ + ป้องกัน stress ulcer — ไม่หยุดโภชนาการทั้งหมด',
  'คุมไม่ได้ → เปลี่ยนยาทาแผล เช่น mafenide ซึมผ่าน eschar ได้ดีที่สุด',
  'แผลบ่งบอก invasive infection: จุดดำหรือม่วง eschar หลุดเร็ว ขอบแผลบวมแดง แผลตื้นกลายเป็นลึก'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงกับสไลด์หน้า 70 และชีทหน้า 24 ที่ให้กำจัดสาเหตุก่อนร่วมกับดูแลหัวใจ ปอด และทางเดินอาหาร · Surviving Sepsis Campaign 2021 เสริมเรื่องเวลา: ให้ยาฆ่าเชื้อภายใน 1 ชั่วโมงเมื่อมี shock และทำ source control เร็วที่สุดเท่าที่ทำได้ · สไลด์ไม่ได้ระบุชนิดยา แนวปัจจุบันเลือกตาม antibiogram ของหน่วย ซึ่งมักต้องคลุม MRSA และ Pseudomonas ที่ดื้อยา',
 mnemonic='<b>“Septic burn = หัวใจปอด + ลำไส้ + ตัดแผล + ยา”</b>',
 guide="Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021 (Crit Care Med 2021;49:e1063–e1143); ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon's Total Burn Care 5th ed. (2018)",
 variants=['ชายไหม้ 40% septic shock เพาะเชื้อแผลพบ Pseudomonas ที่ไวต่อ colistin เพียงตัวเดียว → ตัดเนื้อตายและให้ยาตามผลความไว เฝ้าระวังพิษต่อไต',
  'ชายไหม้ 60% septic shock แผลติดเชื้อหลายส่วน แต่ความดันยังไม่นิ่งพอผ่าตัดใหญ่ → resuscitate แล้วตัดเนื้อตายเป็นช่วง ๆ เริ่มจากส่วนที่แย่ที่สุดก่อน',
  'เด็กไหม้ 10% วันที่ 3 ไข้สูง ผื่นแดงทั่วตัว ความดันต่ำ ทั้งที่แผลดูไม่ติดเชื้อ → toxic shock syndrome จาก S. aureus ให้สารน้ำ ยาคลุม staphylococcus ร่วมกับ clindamycin ลดการสร้าง toxin'])

mk(Q, 113, [69, 's23'],
 stem='A 30-year-old man has 40% TBSA burns. On day 8 one area of eschar develops dark discoloration, and a biopsy of the eschar with underlying tissue is sent for quantitative culture. Which result supports invasive burn wound infection?',
 opts=['More than 10⁵ organisms per gram of tissue','More than 10³ colony-forming units per milliliter of blood','Heavy growth on a swab of the wound surface','More than 10² organisms per gram of tissue','More than 10⁵ colony-forming units per milliliter of urine'],
 interp='ไหม้ 40% วันที่ 8 eschar บางจุดเปลี่ยนเป็นสีดำ ตัดชิ้นเนื้อ eschar พร้อมเนื้อข้างใต้ไปทำ quantitative culture → สงสัย invasive burn wound infection → ถามค่าตัดสินที่สนับสนุน ต้องรู้ทั้งเกณฑ์ ตัวเลข และหน่วยของการตรวจนี้',
 why='<b>Quantitative eschar culture</b> คือตัดชิ้นเนื้อแผลขนาดเล็ก ชั่งน้ำหนัก บดเนื้อ แล้วเพาะเชื้อแบบเจือจางเป็นลำดับเพื่อนับจำนวนเชื้อ<b>ต่อกรัมเนื้อเยื่อ</b> · เกณฑ์ <b>&gt; 10⁵ organisms/g</b> ถือว่ามีการติดเชื้อชนิดนั้น เพราะเป็นระดับที่เชื้อเริ่มเอาชนะกลไกป้องกันเฉพาะที่ และพบร่วมกับแผลเสื่อมลงและกราฟต์ไม่ติด · ข้อจำกัด: บอกจำนวนแต่ไม่บอกว่าเชื้ออยู่ใน eschar ที่ตายหรือบุกเนื้อที่มีชีวิต หลายรายที่จำนวนเชื้อสูงยังไม่พบการบุกใน histology ซึ่งเป็นตัวตัดสินที่แม่นกว่า · ประโยชน์หลักคือทำ<b>สัปดาห์ละ 1–2 ครั้ง</b>เพื่อรู้ resident flora ของแผล ไว้เลือกยาทันทีเมื่อผู้ป่วยเริ่มมีอาการติดเชื้อ · swab ผิวแผลไม่ได้เนื้อเยื่อ จึงใช้เกณฑ์นี้ไม่ได้ · ชีทหน้า 23 <b>"เมื่อพบว่ามีเชื้อเพาะขึ้นมากกว่า 10<sup>5</sup> ตัวต่อกรัมของเนื้อบาดแผลที่นำไปเพาะ (Organism/gram tissue)ให้ถือว่ามีการติดเชื้อชนิดนั้น"</b>',
 wrong={
 'B':'ค่าต่อ mL ของเลือดเป็นหน่วยของ blood culture ใช้วินิจฉัยการติดเชื้อในกระแสเลือด ไม่ได้วัดจำนวนเชื้อในแผล และสิ่งที่ส่งตรวจคือชิ้นเนื้อ eschar ไม่ใช่เลือด · ไม่มีสถานการณ์ใดที่ค่าต่อ mL ของเลือดเป็นเกณฑ์ของ invasive burn wound infection เพราะเกณฑ์ของแผลนับต่อกรัมเนื้อเยื่อเสมอ',
 'C':'Swab ผิวแผลเก็บได้แค่เชื้อบนผิว eschar ซึ่งแผลไหม้แทบทุกแผลมีเชื้อ colonize หลังวันที่ 3–5 การขึ้นเชื้อมากจึงบอกแค่ว่ามีเชื้อ ไม่บอกว่าบุกเนื้อ · ไม่มีสถานการณ์ใดที่ swab ผิวแผลขึ้นเชื้อมากสนับสนุน invasive infection ได้ด้วยตัวเอง เพราะ swab ไม่มีเนื้อเยื่อให้ประเมินความลึก แม้จะช่วยบอกชนิดเชื้อบนแผลได้',
 'D':'10² ต่อกรัมเป็นจำนวนเชื้อที่ต่ำกว่าเกณฑ์ถึงพันเท่า พบได้ในแผลที่มีเชื้อปนเปื้อนเล็กน้อยหรือแผลที่ยาทาควบคุมเชื้อได้ดี และเป็นพื้นแผลที่พร้อมปลูกผิว · ไม่มีสถานการณ์ใดที่ 10² ต่อกรัมเป็นเกณฑ์สนับสนุน invasive burn wound infection เพราะเกณฑ์มาตรฐานของ quantitative culture คือมากกว่า 10⁵ ต่อกรัม',
 'E':'&gt; 10⁵ CFU ต่อ mL ของปัสสาวะเป็นเกณฑ์ UTI แบบดั้งเดิม ใช้ตัวเลขเดียวกันแต่คนละสิ่งส่งตรวจและคนละหน่วย จึงเป็นตัวลวงที่จำสับสนง่าย · ไม่มีสถานการณ์ใดที่ผลเพาะเชื้อปัสสาวะใช้ตัดสิน invasive burn wound infection เพราะสะท้อนการติดเชื้อทางเดินปัสสาวะซึ่งเป็นอีกแหล่งหนึ่งของ burn sepsis'},
 trap='ตัวเลข 10⁵ ปรากฏทั้งเกณฑ์แผลและเกณฑ์ปัสสาวะ ส่วน swab ก็ฟังเหมือนเพาะเชื้อจากแผลเช่นกัน · วิธีแยก: ตรวจให้ครบ 3 อย่าง — สิ่งส่งตรวจต้องเป็นชิ้นเนื้อแผล หน่วยต้องเป็นต่อกรัมเนื้อเยื่อ และค่าต้องเกิน 10⁵',
 summary=['เกณฑ์ quantitative eschar culture: &gt; 10⁵ organisms ต่อกรัมเนื้อเยื่อ = มีการติดเชื้อชนิดนั้น (สไลด์หน้า 69)',
  'สิ่งส่งตรวจ = ชิ้นเนื้อ eschar พร้อมเนื้อข้างใต้ จากจุดที่แผลเปลี่ยน ไม่ใช่ swab',
  'ชีทหน้า 23: ทำสัปดาห์ละ 1–2 ครั้งเพื่อรู้ resident flora ไว้เลือกยาเมื่อเริ่มติดเชื้อ',
  'จุดอ่อน: บอกจำนวน ไม่บอกตำแหน่ง — histology ที่เห็นเชื้อบุก subeschar tissue แม่นกว่า',
  'สัญญาณแผลที่ควรตัดชิ้นเนื้อ: สีดำหรือม่วงเป็นจุด · eschar หลุดเร็ว · ขอบแผลแดงบวม · แผลตื้นกลายเป็นลึก',
  'ชีทหน้า 23: แต่ละหน่วยไฟไหม้ต้องรู้เชื้อประจำหน่วย — Pseudomonas aeruginosa และ S. aureus พบบ่อยที่สุด'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — สไลด์หน้า 69 และชีทหน้า 23 ใช้เกณฑ์ &gt; 10⁵ ต่อกรัมเนื้อเยื่อตรงกัน · แต่ ABA consensus 2007 และตำราปัจจุบันให้ histology เป็นหลักในการวินิจฉัย invasive infection เพราะ quantitative culture ไม่แยกเชื้อใน eschar ออกจากเชื้อในเนื้อดี หลายศูนย์จึงเลิกทำ culture ตามรอบ ใช้การตรวจแผลทุกวันร่วมกับตัดชิ้นเนื้อเมื่อแผลเปลี่ยน ซึ่งชีทหน้า 23 เองก็ยอมรับว่ามีข้อถกเถียงเรื่องนี้',
 mnemonic='<b>“ชิ้นเนื้อ · ต่อกรัม · เกินแสน (10⁵)”</b>',
 guide="ABA Consensus Conference to Define Sepsis and Infection in Burns (J Burn Care Res 2007;28:776–790); Herndon's Total Burn Care 5th ed. (2018) — Burn wound infections; Sabiston Textbook of Surgery 21st ed. (2022) — Burns",
 variants=['ผู้ป่วยไหม้ 45% มีไข้และแผลเปลี่ยน แต่โรงพยาบาลไม่มี quantitative culture → ส่งชิ้นเนื้อตรวจ histology ร่วมกับเพาะเชื้อทั่วไปเพื่อบอกชนิดเชื้อและความไวของยา',
  'ปลูกผิวแล้วกราฟต์ละลายหายเกือบทั้งแผ่นใน 3 วัน แม้ quantitative culture ก่อนผ่าตัดต่ำกว่า 10⁵ → นึกถึง β-hemolytic streptococcus ที่ทำลายกราฟต์ได้แม้จำนวนน้อย ให้ penicillin',
  'หน่วยไฟไหม้ที่ทำ quantitative culture สัปดาห์ละ 2 ครั้ง พบ Acinetobacter ดื้อยาในหลายเตียง → แจ้งงานควบคุมการติดเชื้อ แยกผู้ป่วย และปรับยา empirical ของหน่วยตามเชื้อใหม่'])

mk(Q, 114, [69, 's23'],
 stem='A 33-year-old woman on day 12 after a 45% TBSA burn has a wound area with focal black discoloration and early eschar separation. A biopsy is taken. Which histological finding confirms invasive burn wound infection?',
 opts=['Granulation tissue with capillary budding at the base','Dense bacterial colonies confined to the necrotic eschar','Keratin pearls at the margin of the wound','Microorganisms invading the viable subeschar tissue','Thrombosed dermal vessels within the zone of coagulation'],
 interp='ไหม้ 45% วันที่ 12 แผลมีจุดดำและ eschar เริ่มหลุดเร็ว ตัดชิ้นเนื้อ → สงสัย invasive burn wound infection → ถามว่าภาพทางพยาธิแบบไหนยืนยันได้ ต้องแยกเชื้อใน eschar ที่ตาย (colonization) ออกจากเชื้อในเนื้อที่ยังมีชีวิต (invasion)',
 why='Eschar เป็นเนื้อตายที่ไม่มีเลือดเลี้ยง เชื้อจึงเจริญใน eschar ได้โดยร่างกายไม่ตอบสนอง — สิ่งที่แยก <b>invasive infection</b> ออกจาก <b>colonization</b> คือเชื้อข้ามรอยต่อ eschar กับเนื้อดีเข้าไปใน<b>เนื้อที่ยังมีชีวิตใต้ eschar</b> · การจัดระยะทาง histology ตาม Pruitt: <b>ระยะ I colonization</b> — เชื้อบนผิว eschar → แทรกลงใน eschar → เพิ่มจำนวนใน subeschar space · <b>ระยะ II invasion</b> — microinvasion เข้าเนื้อดีเป็นหย่อม → บุกลึกและกว้าง → <b>microvascular involvement</b> เชื้อเข้าหลอดเลือดเล็กและท่อน้ำเหลือง ซึ่งพยากรณ์โรคแย่ที่สุด · ชิ้นเนื้อต้องลึกพอให้ได้ทั้ง eschar และเนื้อดีข้างใต้ จากจุดที่แผลเปลี่ยนมากที่สุด และใช้ frozen section ได้ผลภายในไม่กี่ชั่วโมง จึงตัดสินใจผ่าตัดได้เร็วกว่ารอผลเพาะเชื้อ · สไลด์หน้า 69 <b>"Qualitative: Histological examination · visualization of invading microorganisms of the subeschar tissue"</b>',
 wrong={
 'A':'Granulation tissue ที่มี capillary งอกใหม่เป็นสัญญาณของการหายของแผลและบ่งว่าพื้นแผลพร้อมปลูกผิว แม้พื้นแผลแบบนี้จะติดเชื้อง่ายถ้าเปิดทิ้งไว้นาน แต่ตัวมันเองไม่ใช่หลักฐานการติดเชื้อ · ไม่มีสถานการณ์ใดที่ granulation tissue ใช้ยืนยัน invasive burn wound infection เพราะการยืนยันต้องเห็นตัวเชื้อในเนื้อที่มีชีวิต',
 'B':'เชื้อหนาแน่นที่จำกัดอยู่ใน eschar คือ colonization ระยะ I แม้จำนวนมากจนนับได้เกิน 10⁵ ต่อกรัม ก็ยังไม่ใช่ invasion ตราบใดที่เชื้อไม่ข้ามเข้าเนื้อดี · ไม่มีสถานการณ์ใดที่เชื้อซึ่งอยู่เฉพาะใน eschar ยืนยัน invasive infection ได้ เพราะนิยามของ invasion คือเชื้อในเนื้อที่มีชีวิต การดูแลคือทำแผลด้วยยาทาและตัดเนื้อตายตามแผน',
 'C':'Keratin pearl คือกลุ่ม keratin เรียงเป็นวงซ้อนที่สร้างจาก squamous cell carcinoma ชนิด well-differentiated พบในแผลเป็นไฟไหม้เรื้อรังที่กลายเป็น Marjolin ulcer หลายปีต่อมา ไม่เกี่ยวกับการติดเชื้อ · ไม่มีสถานการณ์ใดที่ keratin pearl ยืนยัน invasive burn wound infection เพราะเป็นลักษณะของมะเร็ง ไม่ใช่ของเชื้อ',
 'E':'Thrombosis ของหลอดเลือดใน zone of coagulation เกิดจากความร้อนโดยตรงตั้งแต่วันแรก เป็นลักษณะปกติของแผลไหม้ลึก ต่างจาก microvascular involvement ที่ต้องเห็นตัวเชื้อในผนังหลอดเลือดของเนื้อดี · ไม่มีสถานการณ์ใดที่หลอดเลือดอุดใน zone of coagulation อย่างเดียวยืนยัน invasive infection เพราะพบในแผลไหม้ลึกทุกแผลแม้ไม่ติดเชื้อ'},
 trap='ช้อย B ฟังน่ากลัวเพราะเชื้อหนาแน่น และช้อย E มีคำว่าหลอดเลือดอุดซึ่งชวนนึกถึงระยะ microvascular · วิธีแยก: ถามว่าเชื้ออยู่ในเนื้อที่ตายหรือเนื้อที่ยังมีชีวิต — ปริมาณเชื้อมากแค่ไหนก็ไม่สำคัญเท่าตำแหน่งของเชื้อ',
 summary=['ยืนยัน invasive burn wound infection = เห็นเชื้อบุกเนื้อที่มีชีวิตใต้ eschar ใน histology (สไลด์หน้า 69)',
  'Pruitt ระยะ I colonization: บนผิว eschar → แทรกใน eschar → เพิ่มจำนวนใน subeschar space',
  'Pruitt ระยะ II invasion: microinvasion → บุกลึกกว้าง → microvascular involvement (แย่ที่สุด)',
  'ชีทหน้า 23: histology แม่นกว่า quantitative culture ในการหาเชื้อที่บุก subeschar tissue',
  'ชิ้นเนื้อต้องได้ทั้ง eschar และเนื้อดีข้างใต้ จากจุดที่แผลเปลี่ยนมากที่สุด · frozen section ให้ผลเร็ว',
  'ย้อมพิเศษ (GMS, PAS) ช่วยหาเชื้อรา — เส้นใยราบุกหลอดเลือด = invasive fungal infection ต้องตัดกว้าง'],
 opinion='เห็นด้วยกับคำตอบ D ความมั่นใจสูง — สไลด์หน้า 69 ใช้นิยามนี้ตรงตัว และ ABA consensus 2007 ใช้ histology ที่เห็นเชื้อบุกเนื้อดีเป็นเกณฑ์ของ invasive infection เช่นเดียวกัน · ชีทหน้า 23 ยังเรียก quantitative culture ว่าเป็นมาตรฐาน แต่ยอมรับว่าแม่นไม่เท่า histology — ตำราปัจจุบัน (Herndon 2018) ถือ histology เป็นวิธีที่เชื่อถือได้ที่สุด ส่วนการเพาะเชื้อใช้บอกชนิดและความไวของยา',
 mnemonic='<b>“เนื้อตายมีเชื้อ = colonize · เนื้อเป็นมีเชื้อ = invade”</b>',
 guide="Herndon's Total Burn Care 5th ed. (2018) — Burn wound infections; ABA Consensus Conference to Define Sepsis and Infection in Burns (J Burn Care Res 2007;28:776–790)",
 variants=['ชิ้นเนื้อแผลไหม้พบเส้นใยราแตกกิ่งมุมแหลมบุกเข้าผนังหลอดเลือดของเนื้อดี → invasive Aspergillus ตัดเนื้อกว้างจนถึงเนื้อดีและให้ voriconazole',
  'ผล frozen section พบเชื้อเฉพาะใน eschar ไม่ข้ามเข้าเนื้อดี และผู้ป่วยไม่มีอาการทั่วร่าง → colonization ทำแผลด้วยยาทาต่อและตัดเนื้อตายตามแผนเดิม',
  'แผล partial thickness ที่กำลังหายกลายเป็น full thickness ภายใน 2 วัน → สัญญาณ invasive infection ที่ทำให้ zone of stasis ตาย ตัดชิ้นเนื้อและเร่งตัดเนื้อตาย',
  'ตุ่มน้ำใสเป็นกลุ่มบนแผลไหม้ที่หน้าซึ่งกำลังหาย → HSV ส่ง PCR และให้ acyclovir'])

mk(Q, 115, [69, 's23'],
 stem='A 45-year-old man on day 7 after a 35% TBSA burn has a surface swab that grows Pseudomonas aeruginosa. The wound looks unchanged, and he is afebrile with stable vital signs. What best distinguishes invasive infection from colonization?',
 opts=['A single serum procalcitonin measurement','Tissue biopsy for quantitative culture and histology','Daily surface swabs until two cultures agree','Antibiotic susceptibility testing of the swab isolate','Empirical systemic antibiotics and observing the response'],
 interp='ไหม้ 35% วันที่ 7 swab ผิวแผลขึ้น Pseudomonas aeruginosa แต่แผลไม่เปลี่ยน ไม่มีไข้ สัญญาณชีพปกติ → น่าจะเป็นเพียง colonization → ถามวิธีที่แยก invasive infection กับ colonization ได้ดีที่สุด ต้องรู้ว่าการแยกต้องอาศัยเนื้อเยื่อ',
 why='หลังวันที่ 3–5 แผลไหม้แทบทุกแผลมีเชื้อ colonize — ช่วงแรกเป็น gram-positive จากผิวและต่อมที่รอดจากความร้อน แล้วตามด้วย gram-negative อย่าง Pseudomonas · <b>swab</b> เก็บได้เฉพาะเชื้อบนผิว จึงบอกได้แค่ชนิดเชื้อ ไม่บอกว่าเชื้อลงลึกแค่ไหน · การแยกต้องใช้<b>ชิ้นเนื้อ</b>ที่ลึกถึงเนื้อดีใต้ eschar แล้วส่งสองทาง: <b>quantitative culture</b> นับเชื้อ &gt; 10⁵ ต่อกรัม และ <b>histology</b> ดูว่าเชื้อบุก <b>viable subeschar tissue</b> หรือไม่ ซึ่งเป็นตัวตัดสินที่แม่นกว่า · ตัดชิ้นเนื้อเมื่อแผลเปลี่ยน (จุดดำหรือม่วง eschar หลุดเร็ว ขอบแดงบวม) หรือมีอาการทั่วร่าง ไม่ใช่เพียงเพราะ swab ขึ้นเชื้อ · การให้ยาฆ่าเชื้อเข้าระบบใน colonization ไม่ช่วยและเร่งให้เกิดเชื้อดื้อยา · ชีทหน้า 23 <b>"อาจจะมีการถกเถียงว่าไม่ดีเท่ากับการตรวจทางจุลกายวิภาค(Histology) เพื่อตรวจว่าพบเชื้อ (invading microorganism)ในชั้นใต้เนื้อที่ตาย(subeschar tissue)"</b>',
 wrong={
 'A':'Procalcitonin สูงขึ้นในการติดเชื้อแบคทีเรียทั่วร่าง แต่ใน burn ค่าขึ้นได้จากการอักเสบและการบาดเจ็บเอง และไม่บอกตำแหน่งว่าเชื้ออยู่ที่แผลหรือที่อื่น การวัดครั้งเดียวจึงยิ่งแปลยาก · ไม่มีสถานการณ์ใดที่ procalcitonin ครั้งเดียวแยก invasive wound infection ออกจาก colonization ได้ดีที่สุด เพราะการแยกต้องรู้ว่าเชื้อบุกเนื้อหรือไม่ ซึ่งต้องดูจากเนื้อเยื่อ',
 'C':'Swab ซ้ำทุกวันบอกได้แค่ว่าเชื้อชนิดเดิมยังอยู่บนผิว ผลตรงกันสองครั้งยืนยันเพียง colonization ที่คงอยู่ ไม่ได้บอกความลึก และเพิ่มงานโดยไม่เปลี่ยนการรักษา · ไม่มีสถานการณ์ใดที่ swab ผิวแผลซ้ำกี่ครั้งก็ตามแยก invasive infection ได้ เพราะ swab ไม่ได้เนื้อที่มีชีวิตใต้ eschar มาประเมิน',
 'D':'ผลความไวของยาบอกว่าจะเลือกยาอะไรเมื่อถึงเวลาต้องรักษา และมีประโยชน์ในการเฝ้าระวังเชื้อประจำแผล แต่ไม่บอกว่าเชื้อกำลังบุกเนื้อหรือแค่อาศัยบนผิว · ไม่มีสถานการณ์ใดที่ผล susceptibility ใช้แยก invasive infection ออกจาก colonization เพราะเชื้อที่ไวหรือดื้อยาก็ colonize หรือ invade ได้เหมือนกัน',
 'E':'การให้ยาแล้วดูการตอบสนองเป็นการรักษาแบบเดา ใช้ในผู้ป่วยที่มีอาการ sepsis แล้ว แม้ ABA 2007 จะนับการตอบสนองต่อยาเป็นหลักฐานประกอบการติดเชื้อทั่วร่าง แต่ไม่บอกว่าแผลถูกบุกหรือไม่ และเพิ่มเชื้อดื้อยา · ไม่มีสถานการณ์ใดที่การตอบสนองต่อยาเป็นวิธีที่ดีที่สุดในการแยก invasive wound infection กับ colonization เพราะอาการดีขึ้นได้จากหลายปัจจัยนอกแผล'},
 trap='ชื่อ Pseudomonas aeruginosa ฟังอันตรายจนอยากให้ยาทันทีหรือส่งตรวจซ้ำ · วิธีแยก: ผลเพาะเชื้อจาก swab บอกว่า “เชื้ออะไร” แต่ไม่บอกว่า “ลึกแค่ไหน” — คำถามเรื่องความลึกต้องตอบด้วยชิ้นเนื้อ และตัดสินใจรักษาจากแผลร่วมกับอาการของผู้ป่วย',
 summary=['แยก invasive กับ colonization = ชิ้นเนื้อ: quantitative culture &gt; 10⁵ ต่อกรัม + histology เห็นเชื้อบุกเนื้อดี (สไลด์หน้า 69)',
  'Swab บอกชนิดเชื้อบนผิวเท่านั้น — แผลไหม้แทบทุกแผลมีเชื้อ colonize หลังวันที่ 3–5',
  'ลำดับเชื้อบนแผล: gram-positive ช่วงแรก → gram-negative เช่น Pseudomonas ช่วงหลัง · Candida เป็นเชื้อราที่พบบ่อยที่สุด (ชีทหน้า 23)',
  'ชีทหน้า 23: ยาฆ่าเชื้อแบบป้องกันไม่ค่อยมีประโยชน์เมื่อใช้ยาทาแผลอยู่ ให้ยาเข้าระบบเมื่อติดเชื้อชัดเจน',
  'Colonization: แผลไม่เปลี่ยน ไม่มีอาการ → ทำแผล ตัดเนื้อตายตามแผน · Invasive: แผลเปลี่ยน + อาการ sepsis → ชิ้นเนื้อ ตัดเนื้อ ยาเข้าระบบ',
  'Pseudomonas บนแผลมักมีขุยสีเขียวและกลิ่นหวาน — ยังเป็นแค่ colonization ได้ถ้าเนื้อดีไม่ถูกบุก'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — สไลด์หน้า 69 ให้ทั้ง quantitative culture และ histology เป็นวิธีเฝ้าระวังแผล และชีทหน้า 23 ระบุว่า histology แม่นกว่า · ABA consensus 2007 นิยาม invasive infection จากการบุกเนื้อดีใน histology ร่วมกับอาการทางคลินิก และหลัก antimicrobial stewardship ไม่รักษา colonization ด้วยยาเข้าระบบ · ในทางปฏิบัติไม่ตัดชิ้นเนื้อทุกครั้งที่ swab ขึ้นเชื้อ แต่ตัดเมื่อแผลเปลี่ยนหรือมีอาการทั่วร่าง',
 mnemonic='<b>“Swab บอกว่าใคร · Biopsy บอกว่าลึกแค่ไหน”</b>',
 guide="ABA Consensus Conference to Define Sepsis and Infection in Burns (J Burn Care Res 2007;28:776–790); ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon's Total Burn Care 5th ed. (2018)",
 variants=['แผลเดิมที่ swab ขึ้น Pseudomonas เริ่มมีจุดม่วงดำ ขอบบวมแดง ร่วมกับไข้ 39.5 °C และความดันต่ำ → invasive infection ส่งชิ้นเนื้อ ให้ยาคลุม Pseudomonas และตัดเนื้อตายทันที',
  'ผู้ป่วยไหม้มีรอยโรคดำตรงกลางล้อมด้วยขอบแดงบนผิวปกติที่ห่างจากแผล → ecthyma gangrenosum จาก Pseudomonas bacteremia เพาะเชื้อเลือดและให้ยาเข้าหลอดเลือดทันที',
  'ไหม้ 20% แผลปกติ swab ขึ้น MRSA โดยไม่มีอาการ → ถือเป็น colonization ใช้ contact precautions ไม่ต้องให้ vancomycin'])

mk(Q, 116, [73, 's31'],
 stem='A 176-lb woman has 25% TBSA burns. Using the Curreri formula, what is her daily caloric requirement?',
 opts=['2,000 kcal per day','5,400 kcal per day','5,675 kcal per day','11,435 kcal per day','3,000 kcal per day'],
 interp='หญิงหนัก 176 ปอนด์ ไหม้ 25% → ให้คำนวณพลังงานต่อวันด้วย Curreri ซึ่งใช้น้ำหนักเป็นกิโลกรัม → ต้องแปลงหน่วยก่อน แล้วรวมส่วนน้ำหนักกับส่วนแผลไหม้ให้ครบทั้งสองส่วน',
 why='สูตร <b>Curreri</b> สำหรับผู้ใหญ่ = <b>25 kcal × น้ำหนัก (kg) + 40 kcal × %TBSA</b> · ขั้นที่ 1 แปลงหน่วย: <b>176 ÷ 2.2 = 80 kg</b> · ขั้นที่ 2 ส่วนน้ำหนัก 25 × 80 = 2,000 kcal (ใกล้ความต้องการพื้นฐานของผู้ใหญ่) · ขั้นที่ 3 ส่วนแผล 40 × 25 = 1,000 kcal (สะท้อน hypermetabolism ที่โตตามขนาดแผล) · รวม <b>3,000 kcal/วัน</b> · burn ราว 40% ใช้พลังงานสูงราวสองเท่าของปกติ และ hypermetabolism คงอยู่ตราบที่แผลยังไม่หาย จึงต้องเริ่มให้อาหาร<b>ทางลำไส้</b>เร็ว ส่วนโปรตีนให้ตามอัตราส่วน kcal ต่อกรัมไนโตรเจนราว 100–150 : 1 · ข้อจำกัด: Curreri มัก<b>ให้พลังงานเกิน</b>เมื่อแผลกว้างมากหรือผู้ป่วยอ้วน ปัจจุบันใช้ indirect calorimetry เป็นมาตรฐานเมื่อทำได้ · สไลด์หน้า 73 <b>"Adult · 25kcal/kg body weight plus 40kcal per percentage burn"</b>',
 wrong={
 'A':'2,000 kcal คือส่วนน้ำหนักอย่างเดียว (25 × 80) ลืมบวกส่วนที่เพิ่มตามแผล ได้พลังงานเท่าผู้ใหญ่ที่ไม่บาดเจ็บ ซึ่งต่ำไปมากในภาวะ hypermetabolism · จะถูกถ้าหญิงหนัก 48 kg ไหม้ 20% ซึ่ง Curreri ได้ 25 × 48 + 40 × 20 = 1,200 + 800 = 2,000 kcal/วัน',
 'B':'5,400 kcal เกิดจากใส่ 176 เป็นกิโลกรัมโดยไม่แปลงปอนด์ (25 × 176 + 1,000) ส่วนน้ำหนักจึงเกินจริงกว่าสองเท่า · จะถูกถ้าชายหนัก 136 kg ไหม้ 50% ซึ่ง Curreri ได้ 3,400 + 2,000 = 5,400 kcal/วัน — แม้ตัวเลขถูกตามสูตร ค่านี้ในคนอ้วนที่แผลกว้างมักเกินความต้องการจริง',
 'C':'5,675 kcal มาจากการใช้สูตรเด็ก (Davies 60 × 80 + 35 × 25) กับผู้ใหญ่ ส่วนน้ำหนัก 60 kcal/kg สูงเกินความต้องการของผู้ใหญ่ราวสองเท่าครึ่ง · จะถูกถ้าชายหนัก 147 kg ไหม้ 50% ซึ่ง Curreri ได้ 3,675 + 2,000 = 5,675 kcal/วัน',
 'D':'11,435 kcal เป็นความผิดสองชั้น คือใช้สูตรเด็กร่วมกับไม่แปลงปอนด์ (60 × 176 + 35 × 25) ได้ค่าราวสี่เท่าของที่ถูก · ไม่มีสถานการณ์ใดที่ Curreri ให้ค่านี้ในผู้ใหญ่ที่เป็นไปได้จริง เพราะต้องหนักราว 300 kg ขึ้นไปแม้ไหม้ทั้งตัว และหลายศูนย์จำกัด %TBSA ในสูตรไว้ไม่เกิน 50%'},
 trap='เห็น 176 แล้วใส่สูตรทันทีจะได้ 5,400 ซึ่งดูสมเหตุผลเพราะแผลกว้าง · วิธีแยก: ตรวจหน่วยก่อนทุกครั้ง (lb ÷ 2.2) และตรวจว่าคำตอบมีสองส่วน — ส่วนน้ำหนักควรใกล้ 25 kcal/kg ของผู้ใหญ่ทั่วไป ส่วนแผลเท่ากับ 40 × %',
 summary=['Curreri ผู้ใหญ่ = 25 kcal/kg + 40 kcal/%TBSA — น้ำหนักต้องเป็น kg (lb ÷ 2.2)',
  'สไลด์หน้า 73 ใช้ชื่อเต็ม Curreri and Luterman formula (1978) และเน้นคำว่า Adult',
  'ชีทหน้า 31: burn ราว 40% ใช้พลังงานสูงเป็นสองเท่าของปกติ · BMR และอุณหภูมิกายสูงแม้ไม่ติดเชื้อ',
  'ชีทหน้า 31: ให้ทางเดินอาหารเป็นหลัก (กินเองหรือ feeding tube) · TPN เมื่อไม่มีทางเลือกอื่น',
  'ชีทหน้า 31: กลูโคสพอเพียงยับยั้งการสลายโปรตีนไปสร้างกลูโคสที่ตับ · ไขมันให้พลังงานแต่ไม่ลดการสลายโปรตีน',
  'โปรตีนตามชีท: kcal ต่อกรัมไนโตรเจน 100–150 : 1'],
 opinion='เห็นด้วยกับคำตอบ E ความมั่นใจสูง — คำนวณตรงตามสไลด์หน้า 73 และชีทหน้า 31 · ความต่างจากแนวปัจจุบัน: ESPEN 2013 และ ASPEN/SCCM 2016 ให้วัดด้วย indirect calorimetry เป็นมาตรฐาน เพราะ Curreri ให้พลังงานเกินโดยเฉพาะแผลกว้างและคนอ้วน — ESPEN แนะนำสมการ Toronto ในผู้ใหญ่เมื่อไม่มีเครื่อง และให้วัดซ้ำเป็นระยะเพราะความต้องการเปลี่ยนไปตามการหายของแผล',
 mnemonic='<b>“ปอนด์หาร 2.2 ก่อนเสมอ · ผู้ใหญ่ 25 บวก 40”</b>',
 guide="ESPEN endorsed recommendations: Nutritional therapy in major burns (Clin Nutr 2013;32:497–502); ASPEN/SCCM Guidelines for Nutrition Support Therapy in the Adult Critically Ill Patient (JPEN 2016;40:159–211); Herndon's Total Burn Care 5th ed. (2018) — Nutrition",
 variants=['ชายไหม้ 35% ได้อาหารครบตาม Curreri แต่ indirect calorimetry วัด REE ได้ต่ำกว่ามาก ร่วมกับน้ำตาลสูงและ CO2 คั่ง → ลดพลังงานตามค่าที่วัด ป้องกัน overfeeding',
  'หญิงไหม้ 30% อ้วนมาก BMI 40 → มักใช้น้ำหนักปรับ (adjusted body weight) ในสูตรแทนน้ำหนักจริง เพื่อไม่ให้พลังงานเกิน',
  'ชายไหม้ 30% ได้กลูโคสทางหลอดเลือดเกิน 5 mg/kg/min น้ำตาลสูงต่อเนื่องและหายใจหอบ → ลดอัตรากลูโคส เพิ่มสัดส่วนไขมันและโปรตีน'])

mk(Q, 117, [73, 's31'],
 stem='A 70-kg man with 40% TBSA flame burns is starting enteral feeding on day 2. Which formula best estimates his daily energy requirement?',
 opts=['4 mL per kg per percent burn as crystalloid','25 kcal per kg with no burn increment','Harris–Benedict basal energy without a stress factor','25 kcal per kg plus 40 kcal per percent burn','60 kcal per kg plus 35 kcal per percent burn, up to 50%'],
 interp='ชาย 70 kg ไหม้ 40% เริ่มให้อาหารทางลำไส้วันที่ 2 → ต้องการพลังงานเพิ่มจาก hypermetabolism → ถามสูตรประมาณพลังงานต่อวันสำหรับผู้ใหญ่ ต้องแยกสูตรพลังงานออกจากสูตรสารน้ำ และแยกสูตรผู้ใหญ่ออกจากสูตรเด็ก',
 why='ผู้ป่วยไหม้กว้างเข้าสู่ <b>hypermetabolic state</b> จาก catecholamine, cortisol และ glucagon ที่สูงขึ้น ร่วมกับเสียความร้อนผ่านแผล — BMR และอุณหภูมิกายสูงขึ้นแม้ไม่ติดเชื้อ มีการสลายโปรตีนกล้ามเนื้อต่อเนื่อง ทำให้กล้ามเนื้อลีบ ภูมิต่ำ และแผลหายช้า · สูตรผู้ใหญ่ที่นิยมคือ <b>Curreri: 25 kcal/kg + 40 kcal/%TBSA</b> — ส่วนแรกคือพลังงานพื้นฐาน ส่วนหลังเพิ่มตามขนาดแผล · ตัวอย่าง 70 kg ไหม้ 40%: 1,750 + 1,600 = <b>3,350 kcal/วัน</b> · เริ่ม <b>enteral feeding</b> เร็ว ดีที่สุดภายใน 4–6 ชั่วโมงหลังบาดเจ็บ ช่วยรักษาเยื่อบุลำไส้ ลด stress ulcer และลดการสลายโปรตีน · สูตรเด็กใช้ <b>Davies 60 kcal/kg + 35 kcal/%</b> แยกต่างหาก ส่วน Parkland เป็นสูตรสารน้ำ · ชีทหน้า 31 <b>"โดยทั่วไปที่นิยมใช้กันในปัจจุบันในผู้ใหญ่คือสูตรที่เสนอโดย Curreri"</b>',
 wrong={
 'A':'4 mL/kg/%TBSA คือ Parkland สำหรับคำนวณ crystalloid ใน 24 ชั่วโมงแรก มีโครงสร้าง kg กับ % เหมือนกันจึงจำสลับง่าย แต่หน่วยเป็น mL ของสารน้ำ ไม่ใช่พลังงาน · ไม่มีสถานการณ์ใดที่ Parkland ใช้ประมาณพลังงานต่อวัน เพราะเป็นสูตรทดแทนน้ำที่รั่วออกจากหลอดเลือดในระยะ resuscitation',
 'B':'25 kcal/kg โดยไม่บวกส่วนแผลเป็นเป้าพลังงานของผู้ป่วยวิกฤตทั่วไป (ASPEN/SCCM 2016 ให้ 25–30 kcal/kg/วัน) ไม่ครอบคลุม hypermetabolism ที่โตตามขนาดแผลไหม้ · จะถูกถ้าชายหนัก 70 kg ใส่เครื่องช่วยหายใจหลังผ่าตัดลำไส้ทะลุ ไม่มีแผลไหม้ และหอผู้ป่วยไม่มีเครื่อง indirect calorimetry',
 'C':'Harris–Benedict คำนวณ basal energy expenditure จากเพศ อายุ น้ำหนัก และส่วนสูงของคนสุขภาพดี ถ้าไม่คูณ stress factor จะต่ำกว่าความต้องการจริงของ burn มาก · จะถูกถ้าหญิงสุขภาพดีอายุ 40 ปีที่ไม่ได้บาดเจ็บ ต้องการประเมินพลังงานพื้นฐานเพื่อวางแผนอาหารลดน้ำหนัก',
 'E':'60 kcal/kg + 35 kcal/% คือสูตร Davies สำหรับเด็กที่แผลไม่เกิน 50% ส่วนน้ำหนักสูงเพราะเด็กมีพื้นที่ผิวต่อน้ำหนักมากและต้องใช้พลังงานเพื่อเจริญเติบโต ใช้กับผู้ใหญ่จะได้ค่าเกินมาก · จะถูกถ้าเด็กชายอายุ 6 ปีหนัก 22 kg ไหม้ 35% จากเปลวไฟ ที่เริ่มให้อาหารทางสายในวันที่ 2'},
 trap='สูตร Parkland และ Davies มีโครงสร้าง “ตัวเลขต่อ kg กับ %TBSA” เหมือน Curreri จึงสลับกันง่าย · วิธีแยก 2 ขั้น: ถามเรื่องอะไร (สารน้ำ = mL · พลังงาน = kcal) → ผู้ใหญ่หรือเด็ก (ผู้ใหญ่ 25 + 40 · เด็ก 60 + 35 สำหรับแผลไม่เกิน 50%)',
 summary=['พลังงานผู้ใหญ่ = Curreri and Luterman: 25 kcal/kg + 40 kcal/%TBSA (สไลด์หน้า 73)',
  'เด็ก = Davies 60 kcal/kg + 35 kcal/% สำหรับแผลไม่เกิน 50% · Parkland 4 mL/kg/% = สารน้ำ ไม่ใช่พลังงาน',
  'Hypermetabolism: catecholamine, cortisol, glucagon สูง → BMR และอุณหภูมิกายสูง สลายโปรตีน กล้ามเนื้อลีบ',
  'เริ่ม enteral feeding ภายใน 4–6 ชั่วโมงถ้าทำได้ (ASPEN/SCCM 2016) · TPN เมื่อไม่มีทางอื่น (ชีทหน้า 31)',
  'โปรตีนสูง 1.5–2 g/kg/วัน ในผู้ใหญ่ไฟไหม้ (ASPEN/SCCM 2016)',
  'มาตรฐานปัจจุบัน = indirect calorimetry · ไม่มีเครื่อง → ESPEN 2013 ใช้สมการ Toronto ในผู้ใหญ่ Schofield ในเด็ก'],
 opinion='เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ตรงกับสไลด์หน้า 73 และชีทหน้า 31 ที่เรียก Curreri ว่าสูตรที่นิยมในผู้ใหญ่ · แต่คำว่า “นิยมในปัจจุบัน” ของชีทไม่ตรงกับแนวทางปัจจุบันแล้ว: ESPEN 2013 และ ASPEN/SCCM 2016 ให้ indirect calorimetry เป็นมาตรฐาน เพราะ Curreri ให้ค่าเกินจริงในแผลกว้าง ทำให้น้ำตาลสูง ไขมันพอกตับ และ CO2 คั่ง — Curreri ยังใช้ได้เป็นค่าประมาณเริ่มต้นเมื่อไม่มีเครื่อง',
 mnemonic='<b>“ผู้ใหญ่ 25–40 (Curreri) · เด็ก 60–35 (Davies) · เลข 4 คือน้ำ (Parkland)”</b>',
 guide="ESPEN endorsed recommendations: Nutritional therapy in major burns (Clin Nutr 2013;32:497–502); ASPEN/SCCM Guidelines for Nutrition Support Therapy in the Adult Critically Ill Patient (JPEN 2016;40:159–211); Sabiston Textbook of Surgery 21st ed. (2022) — Burns",
 variants=['ผู้ป่วยไหม้ 40% ได้ propofol ทางหลอดเลือดขนาดสูงต่อเนื่อง → นับพลังงานจากไขมันใน propofol (ราว 1.1 kcal/mL) รวมในเป้า ป้องกัน overfeeding',
  'หญิงไหม้ 40% ได้อาหารทางสายตามเป้า แต่น้ำตาลในเลือดเกิน 180 mg/dL ต่อเนื่อง → ให้ insulin คุมน้ำตาล ไม่ลดอาหารจนต่ำกว่าเป้า',
  'ชายไหม้ 50% ท้องอืด รับอาหารทางกระเพาะไม่ได้ → ใส่สายให้อาหารผ่านเลยกระเพาะไปลำไส้เล็ก (post-pyloric) ก่อนพิจารณา TPN'])

mk(Q, 118, [74, 's31'],
 stem='A 20-kg child has 30% TBSA burns. Using the Davies formula, what is the daily caloric requirement?',
 opts=['1,200 kcal per day','2,250 kcal per day','1,700 kcal per day','3,690 kcal per day','22,200 kcal per day'],
 interp='เด็กหนัก 20 kg ไหม้ 30% (ยังไม่เกิน 50% จึงใช้ Davies ได้) → ให้คำนวณพลังงานต่อวัน ต้องคูณส่วนน้ำหนักและส่วนแผลแยกกันแล้วบวก ไม่ใช่คูณน้ำหนักกับ %TBSA แบบ Parkland',
 why='สูตร <b>Davies</b> สำหรับเด็กที่แผล<b>ไม่เกิน 50%</b> = <b>60 kcal × kg + 35 kcal × %TBSA</b> · ส่วนน้ำหนัก 60 × 20 = 1,200 kcal · ส่วนแผล 35 × 30 = 1,050 kcal · รวม <b>2,250 kcal/วัน</b> · ส่วนน้ำหนักของเด็กสูงกว่าผู้ใหญ่ (60 เทียบ 25) เพราะเด็กมี<b>พื้นที่ผิวต่อน้ำหนักมาก</b> เสียความร้อนและน้ำผ่านแผลมากกว่า และยังต้องใช้พลังงานเพื่อ<b>เจริญเติบโต</b> ส่วนแผลจึงคิดต่อ % น้อยกว่าเล็กน้อย (35 เทียบ 40) · สิ่งที่ต่างจาก Parkland คือ Davies <b>บวก</b>สองส่วนแยกกัน ส่วน Parkland <b>คูณ</b> kg × % · เด็กมีไกลโคเจนสำรองน้อย จึงควรเริ่มอาหารทางลำไส้เร็ว และติดตามน้ำหนัก การเจริญเติบโต และน้ำตาลอย่างสม่ำเสมอ · สไลด์หน้า 74 <b>"Child (Up to 50% Burns) · 60 kcal/kg body weight plus 35 kcal per percentage burn"</b>',
 wrong={
 'A':'1,200 kcal คือส่วนน้ำหนักอย่างเดียว (60 × 20) ลืมส่วนที่เพิ่มตามแผล ได้พลังงานใกล้ความต้องการของเด็กที่ไม่บาดเจ็บ ซึ่งไม่พอสำหรับ hypermetabolism · จะถูกถ้าเด็กหนัก 13 kg ไหม้ 12% จากน้ำร้อนลวก ซึ่ง Davies ได้ 780 + 420 = 1,200 kcal/วัน',
 'C':'1,700 kcal มาจากการใช้สูตรผู้ใหญ่ (Curreri 25 × 20 + 40 × 30) กับเด็ก ทำให้ส่วนน้ำหนักต่ำเกินไปมากสำหรับเด็กที่ต้องเติบโตด้วย · จะถูกถ้าเด็กหนัก 19 kg ไหม้ 16% ซึ่ง Davies ได้ 1,140 + 560 = 1,700 kcal/วัน',
 'D':'3,690 kcal เกิดจากใส่น้ำหนักเป็นปอนด์ (44 lb × 60) แทนกิโลกรัม ส่วนน้ำหนักจึงเกินจริงสองเท่ากว่า · จะถูกถ้าเด็กอายุ 10 ปีหนัก 37 kg ไหม้ 42% ซึ่ง Davies ได้ 2,220 + 1,470 = 3,690 kcal/วัน',
 'E':'22,200 kcal เกิดจากคูณ kg × % แบบ Parkland ในส่วนแผล (35 × 20 × 30) ได้ค่าราวสิบเท่าของที่ถูก ซึ่งเด็กไม่มีทางรับได้ · ไม่มีสถานการณ์ใดที่ Davies ให้ค่านี้ในเด็กจริง เพราะต้องหนักราว 340 kg แม้แผลจะกว้างถึง 50% ซึ่งเป็นขีดสูงสุดของสูตร'},
 trap='เคยชินกับ Parkland ที่คูณ kg × % จึงเผลอคูณสามตัวในสูตร Davies หรือหยิบสูตรผู้ใหญ่ที่จำได้ก่อน · วิธีแยก: Davies = สองก้อนบวกกัน ก้อนน้ำหนัก (60 × kg) กับก้อนแผล (35 × %) และผลรวมในเด็กเล็กถึงวัยเรียนมักอยู่ในหลักพันต้น ๆ',
 summary=['Davies (เด็ก แผลไม่เกิน 50%) = 60 kcal/kg + 35 kcal/% — บวกสองส่วน ไม่คูณ kg × %',
  'เด็กใช้ตัวเลขต่อ kg สูงกว่าผู้ใหญ่: พื้นที่ผิวต่อน้ำหนักมาก เสียความร้อนมาก ต้องใช้พลังงานเติบโต',
  'ชีทหน้า 31 ให้สูตรเด็ก 60/35 โดยไม่ระบุชื่อ — ชื่อ Davies อยู่บนสไลด์หน้า 74',
  'เด็กแผลเกิน 50% → สูตรตามพื้นที่ผิวกาย (Galveston) หรือ indirect calorimetry',
  'ความผิดที่พบบ่อย: ลืมส่วนแผล · ใช้ปอนด์ · ใช้สูตรผู้ใหญ่ · คูณ kg × % — ตรวจทุกครั้งว่ามีสองก้อน',
  'ชีทหน้า 31: ประเมินโภชนาการด้วย serum albumin ช้าเกินไปเพราะครึ่งชีวิตยาว'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — คำนวณตรงตามสไลด์หน้า 74 และชีทหน้า 31 (ชีทให้ตัวเลข 60/35 แต่ไม่ระบุชื่อ Davies ซึ่งอยู่บนสไลด์) · แนวปัจจุบัน ESPEN 2013 ให้ indirect calorimetry เป็นมาตรฐานในเด็กเช่นกัน และถ้าไม่มีเครื่องแนะนำสมการ Schofield ส่วนศูนย์ในสหรัฐนิยมสูตร Galveston ตามพื้นที่ผิวกาย เพราะสูตรตามน้ำหนักให้ค่าเพี้ยนได้มากในเด็กตัวเล็กหรือแผลกว้าง',
 mnemonic='<b>“Davies = 60 บวก 35 — บวก ไม่ใช่คูณ”</b>',
 guide="ESPEN endorsed recommendations: Nutritional therapy in major burns (Clin Nutr 2013;32:497–502); Herndon's Total Burn Care 5th ed. (2018) — Nutrition",
 variants=['เด็กไหม้ 30% ได้อาหารครบตามสูตรแต่แผลหายช้าและ prealbumin ลดลงต่อเนื่อง → ประเมินพลังงานใหม่ด้วย indirect calorimetry และเพิ่มโปรตีน',
  'เด็กไหม้ 25% ได้นมสูตรทางสายแล้วถ่ายเหลวมาก → ปรับอัตราและความเข้มข้นของสูตร หาสาเหตุเช่น C. difficile ก่อนตัดสินใจหยุดอาหาร',
  'เด็กไหม้ 40% หลังพ้นระยะ resuscitation ได้ propranolol → ลดอัตราการเต้นของหัวใจและ catabolism ช่วยรักษามวลกล้ามเนื้อ'])

mk(Q, 119, [74, 's31'],
 stem='A 15-kg 3-year-old boy has 20% TBSA scald burns and is starting tube feeds. Which formula is used to estimate his daily calorie requirement?',
 opts=['Modified Brooke formula','Davies formula','Curreri formula','Toronto equation','Parkland formula'],
 interp='เด็กอายุ 3 ปี หนัก 15 kg ไหม้จากน้ำร้อนลวก 20% เริ่มให้อาหารทางสาย → ถามสูตรประมาณพลังงานต่อวัน ต้องแยก 2 ชั้น: สูตรพลังงานกับสูตรสารน้ำ แล้วแยกสูตรเด็กกับสูตรผู้ใหญ่',
 why='สูตรใน burn แบ่ง 2 กลุ่ม: <b>สารน้ำ</b> (Parkland 4 mL/kg/%, Modified Brooke 2 mL/kg/% — หน่วย mL ใช้ใน 24 ชั่วโมงแรก) และ<b>พลังงาน</b> (หน่วย kcal ต่อวัน) · ในกลุ่มพลังงานแยกตามวัย: ผู้ใหญ่ = <b>Curreri 25 kcal/kg + 40 kcal/%</b> · เด็ก = <b>Davies 60 kcal/kg + 35 kcal/%</b> ใช้กับแผลไม่เกิน 50% · เด็ก 15 kg ไหม้ 20%: 900 + 700 = 1,600 kcal/วัน · เด็กต้องใช้สูตรแยกเพราะสัดส่วนพื้นที่ผิวต่อน้ำหนักสูง เสียความร้อนมาก ต้องเผื่อพลังงานเพื่อเติบโต และไกลโคเจนสำรองน้อยจึงขาดพลังงานเร็ว — ใช้สูตรผู้ใหญ่กับเด็กจะได้ค่าต่ำเกิน · เด็ก scald 20% ยังต้องได้ Parkland ร่วมกับ maintenance ที่มี dextrose ในวันแรกควบคู่ไปด้วย · สไลด์หน้า 74 <b>"Davies Formula · Child (Up to 50% Burns)"</b>',
 wrong={
 'A':'Modified Brooke (2 mL/kg/%TBSA ของ Ringer lactate) เป็นสูตรสารน้ำใน 24 ชั่วโมงแรก ใกล้เคียงกับเป้าเริ่มต้นของ ABA ปัจจุบันในผู้ใหญ่ ไม่ได้ให้ค่าพลังงาน · ไม่มีสถานการณ์ใดที่ Modified Brooke ใช้ประมาณพลังงานต่อวัน เพราะหน่วยเป็น mL ของสารน้ำที่ทดแทนการรั่ว ไม่ใช่ kcal',
 'C':'Curreri (25 kcal/kg + 40 kcal/%) เป็นสูตรพลังงานของผู้ใหญ่ ส่วนน้ำหนักต่ำเกินสำหรับเด็กที่ต้องเติบโต ใช้กับเด็กในโจทย์จะได้ 375 + 800 = 1,175 kcal ต่ำกว่า Davies มาก · จะถูกถ้าชายอายุ 30 ปีหนัก 65 kg ไหม้ 30% จากเปลวไฟที่เริ่มให้อาหารทางสาย',
 'D':'Toronto equation เป็นสมการพลังงานที่พัฒนาในผู้ใหญ่ไฟไหม้ ใช้ %TBSA ร่วมกับพลังงานที่ได้รับ อุณหภูมิกาย จำนวนวันหลังบาดเจ็บ และ BEE จาก Harris–Benedict — ESPEN 2013 แนะนำในผู้ใหญ่เมื่อไม่มี indirect calorimetry แต่ไม่ใช้ในเด็ก · จะถูกถ้าหญิงอายุ 45 ปีไหม้ 35% ในหอที่ไม่มีเครื่อง indirect calorimetry และใช้แนวทาง ESPEN',
 'E':'Parkland (4 mL/kg/%TBSA) คือสูตร crystalloid ใน 24 ชั่วโมงแรก ให้ครึ่งแรกใน 8 ชั่วโมง เด็กรายนั้นต้องใช้ Parkland ร่วมกับ maintenance ในวันแรกจริง แต่ไม่ได้ใช้คิดพลังงาน · ไม่มีสถานการณ์ใดที่ Parkland ใช้ประมาณพลังงานต่อวัน เพราะเป็นสูตรทดแทนน้ำที่รั่วออกนอกหลอดเลือด'},
 trap='สูตรทั้งห้าเป็นสูตรจริงที่ใช้ใน burn และชื่อ Parkland คุ้นที่สุด · วิธีแยก: ดูหน่วยของสิ่งที่ถาม (พลังงาน = kcal · สารน้ำ = mL) แล้วดูวัย — เด็กที่แผลไม่เกิน 50% = Davies · ผู้ใหญ่ = Curreri',
 summary=['เลือกสูตรสองชั้น: สารน้ำ (Parkland, Modified Brooke) vs พลังงาน (Curreri, Davies) → ผู้ใหญ่ vs เด็ก',
  'Davies = เด็กที่แผลไม่เกิน 50%: 60 kcal/kg + 35 kcal/% (สไลด์หน้า 74)',
  'ชีทหน้า 31 ให้ตัวเลข 60/35 สำหรับเด็กโดยไม่ระบุชื่อสูตร',
  'เด็กไหม้วันแรก: Parkland + maintenance ที่มี dextrose (Holliday–Segar 4-2-1) เพราะไกลโคเจนสำรองน้อย',
  'ระยะยาว: hypermetabolism ในเด็กทำให้โตช้านานหลังแผลหาย ต้องติดตามส่วนสูงและน้ำหนัก',
  'แนวปัจจุบัน: indirect calorimetry · ไม่มีเครื่อง → สมการ Schofield ในเด็ก (ESPEN 2013)'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — สไลด์หน้า 74 ระบุ Davies สำหรับเด็กที่แผลถึง 50% และชีทหน้า 31 ให้ตัวเลขเดียวกัน (แต่ไม่ระบุชื่อสูตร) · แนวปัจจุบันไม่ได้ยึด Davies เป็นหลัก: ESPEN 2013 ให้วัด indirect calorimetry และใช้สมการ Schofield เมื่อไม่มีเครื่อง ส่วนหลายศูนย์ใช้สูตร Galveston ตามพื้นที่ผิวกาย — ในบริบทการสอบให้ตอบ Davies ตามที่สอน',
 mnemonic='<b>“mL = น้ำ (Parkland, Brooke) · kcal = กิน (Curreri ผู้ใหญ่, Davies เด็ก)”</b>',
 guide="ESPEN endorsed recommendations: Nutritional therapy in major burns (Clin Nutr 2013;32:497–502); ABA Advanced Burn Life Support Provider Manual (2018); Herndon's Total Burn Care 5th ed. (2018)",
 variants=['เด็ก 15 kg ไหม้ 20% ระหว่าง resuscitation ซึมลง เหงื่อออก น้ำตาลปลายนิ้ว 45 mg/dL → ให้ dextrose ทันทีและตรวจว่าได้ maintenance ที่มี dextrose หรือไม่',
  'เด็กไหม้ 20% กินเองได้ แต่กินไม่ถึง 70% ของเป้า Davies ติดกัน 3 วัน → ใส่ nasogastric tube ให้อาหารเสริม',
  'เด็กไหม้ 15% จากน้ำร้อน แผลขอบเรียบชัดรอบเท้าทั้งสองข้างคล้ายสวมถุงเท้า ไม่มีรอยกระเด็น → สงสัยถูกทำร้าย (immersion burn) แจ้งทีมคุ้มครองเด็ก'])

mk(Q, 120, [74, 's31'],
 stem='A 10-kg toddler has 40% TBSA burns. Using the Davies formula, what is the daily caloric requirement?',
 opts=['2,600 kcal per day','600 kcal per day','1,850 kcal per day','2,000 kcal per day','14,600 kcal per day'],
 interp='เด็กเล็กหนัก 10 kg ไหม้ 40% (ยังไม่เกิน 50% จึงใช้ Davies ได้) → คำนวณพลังงานต่อวัน · จุดสังเกตคือในเด็กตัวเล็กที่แผลกว้าง ส่วนแผลจะมากกว่าส่วนน้ำหนัก ต้องไม่ตัดคำตอบทิ้งเพราะดูสูงเกิน',
 why='<b>Davies</b> = <b>60 kcal × kg + 35 kcal × %TBSA</b> ใช้กับเด็กที่แผล<b>ไม่เกิน 50%</b> · ส่วนน้ำหนัก 60 × 10 = 600 kcal · ส่วนแผล 35 × 40 = <b>1,400 kcal</b> · รวม <b>2,000 kcal/วัน</b> — ราวสองเท่าของความต้องการปกติตาม Holliday–Segar (100 kcal/kg = 1,000 kcal) · ในเด็กเล็กที่แผลกว้าง<b>ส่วนแผลมากกว่าส่วนน้ำหนัก</b> เพราะส่วนแผลไม่ขึ้นกับขนาดตัว · ปริมาณนี้มากสำหรับกระเพาะเด็ก 10 kg จึงมักต้องให้ทางสายต่อเนื่องตลอด 24 ชั่วโมง เริ่มเร็วและเพิ่มอัตราทีละน้อย ใช้สูตรพลังงานสูง และติดตามท้องอืด ถ่ายเหลว น้ำตาล และน้ำหนัก · ในเด็กเล็ก สูตรตามน้ำหนักเพี้ยนได้มากกว่าสูตรตามพื้นที่ผิวกาย จึงควรวัด indirect calorimetry ถ้าทำได้ · สไลด์หน้า 74 <b>"60 kcal/kg body weight plus 35 kcal per percentage burn"</b>',
 wrong={
 'A':'2,600 kcal คือค่าของเด็กที่หนักกว่าเท่าตัว (60 × 20 + 1,400) เกิดจากใส่น้ำหนักผิดหรือคิดส่วนน้ำหนักเกิน ในเด็ก 10 kg จะได้อาหารเกินจนเสี่ยงน้ำตาลสูงและไขมันพอกตับ · จะถูกถ้าเด็กหนัก 20 kg ไหม้ 40% ซึ่ง Davies ได้ 1,200 + 1,400 = 2,600 kcal/วัน',
 'B':'600 kcal คือส่วนน้ำหนักอย่างเดียว (60 × 10) ลืมส่วนแผลซึ่งในเด็กแผลกว้างเป็นก้อนที่ใหญ่กว่า ได้ไม่ถึงหนึ่งในสามของที่ต้องการ · จะถูกถ้าทารกหนัก 3 kg ไหม้ 12% จากน้ำร้อนลวก ซึ่ง Davies ได้ 180 + 420 = 600 kcal/วัน',
 'C':'1,850 kcal มาจากการใช้สูตรผู้ใหญ่ Curreri (25 × 10 + 40 × 40 = 250 + 1,600) กับเด็กเล็ก ทำให้ส่วนน้ำหนักต่ำเกินและส่วนแผลสูงเกิน · จะถูกถ้าเด็กหนัก 25 kg ไหม้ 10% ซึ่ง Davies ได้ 1,500 + 350 = 1,850 kcal/วัน',
 'E':'14,600 kcal เกิดจากคูณ kg × % แบบ Parkland ในส่วนแผล (35 × 10 × 40) ได้ค่าราวเจ็ดเท่าของที่ถูก ซึ่งเป็นไปไม่ได้ทางสรีรวิทยาในเด็ก 10 kg · ไม่มีสถานการณ์ใดที่ Davies ให้ค่านี้ในเด็กจริง เพราะต้องหนักราว 215 kg แม้แผลจะกว้างถึง 50% ซึ่งเป็นขีดสูงสุดของสูตร'},
 trap='คุ้นว่าส่วนน้ำหนักเป็นก้อนหลัก จึงคิดว่าคำตอบต้องใกล้ 60 × kg และเห็น 2,000 ดูสูงเกินสำหรับเด็ก 10 kg · วิธีแยก: คิดสองก้อนแยกกันเสมอ — เด็กตัวเล็กที่แผลกว้าง ก้อนแผล (35 × %) ใหญ่กว่าก้อนน้ำหนักได้',
 summary=['Davies 10 kg ไหม้ 40%: 600 + 1,400 = 2,000 kcal/วัน — ก้อนแผลใหญ่กว่าก้อนน้ำหนัก',
  'Davies ใช้ได้ถึงแผล 50% (สไลด์หน้า 74) · เกินกว่านั้นใช้สูตรตามพื้นที่ผิวกายหรือ indirect calorimetry',
  'เทียบความต้องการปกติ Holliday–Segar 100 kcal/kg ใน 10 kg แรก → ไหม้ 40% ต้องการราวสองเท่า',
  'ให้ทางสายต่อเนื่อง 24 ชั่วโมง เพิ่มอัตราทีละน้อย ติดตามท้องอืด ถ่ายเหลว น้ำตาล น้ำหนัก',
  'ชีทหน้า 31: ให้ทางเดินอาหารเป็นหลัก · TPN เมื่อไม่มีทางเลือกอื่นเพราะภาวะแทรกซ้อนมากกว่า',
  'ชีทหน้า 31: ประเมินสมดุลโปรตีนด้วย urine urea nitrogen 24 ชั่วโมงสัปดาห์ละครั้ง'],
 opinion='เห็นด้วยกับคำตอบ D ความมั่นใจสูง — คำนวณตรงตามสไลด์หน้า 74 และชีทหน้า 31 · ข้อสังเกต: ในเด็กเล็กมากที่แผลกว้าง สูตรตามน้ำหนักให้ค่าเพี้ยนง่ายเพราะส่วนแผลไม่ขึ้นกับขนาดตัว แนวปัจจุบัน ESPEN 2013 ให้ indirect calorimetry เป็นหลัก หรือสมการ Schofield ถ้าไม่มีเครื่อง และหลายศูนย์ใช้สูตรตามพื้นที่ผิวกาย — ค่า 2,000 kcal ในเด็ก 10 kg จึงเป็นเป้าเริ่มต้นที่ต้องปรับตามน้ำหนักและความทนต่ออาหาร',
 mnemonic='<b>“เด็กเล็กแผลกว้าง ก้อนแผลใหญ่กว่าก้อนตัว”</b>',
 guide="ESPEN endorsed recommendations: Nutritional therapy in major burns (Clin Nutr 2013;32:497–502); Herndon's Total Burn Care 5th ed. (2018) — Nutrition; Sabiston Textbook of Surgery 21st ed. (2022) — Burns",
 variants=['เด็ก 10 kg ไหม้ 40% ตัวเย็น อุณหภูมิ 35.5 °C ระหว่างทำแผล → ทำแผลในห้องอุ่นและลดเวลาเปิดแผล เพราะการเสียความร้อนเพิ่มการใช้พลังงาน',
  'ทารก 8 kg ไหม้ 45% ยังดูดนมแม่ได้ → ให้นมแม่ต่อและเสริมด้วยนมพลังงานสูงทางสาย ไม่ต้องหยุดนมแม่',
  'เด็ก 12 kg ไหม้ 35% ได้อาหารตามเป้า แต่ตับโต ALT สูง น้ำตาลสูงต่อเนื่อง → สงสัย overfeeding ทำให้ไขมันพอกตับ ลดพลังงานจากกลูโคส'])

